58		public static String literalToString(long lit, ArgType type, StringUtils stringUtils, boolean fallback, boolean cast) {
59			if (type == null || !type.isTypeKnown()) {
60				String n = Long.toString(lit);
61				if (fallback && Math.abs(lit) > 100) {
62					StringBuilder sb = new StringBuilder();
63					sb.append(n).append("(0x").append(Long.toHexString(lit));
